using System.Globalization;
using System.Reflection;
using System.Text;
using Kosher.Zmanim.HebrewCalendar;
using Xunit;

namespace Kosher.Zmanim.Tests.Golden;

/// <summary>
/// Cross-checks <see cref="JewishCalendar"/>, <see cref="TefilaRules"/> and <see cref="HebrewDateFormatter"/> against values
/// generated by KosherJava 3.1.0 (see <c>tools/golden/GoldenGenerator.java</c>): every parameterless getter of
/// <see cref="JewishCalendar"/> (Jewish date, <em>yom tov</em> index, <em>parshah</em>, <em>daf yomi</em>, <em>molad</em>,
/// <em>kiddush levana</em>, every <c>Is*</c> predicate), every <see cref="TefilaRules"/> predicate and the Hebrew and
/// transliterated output of <see cref="HebrewDateFormatter"/>, for every day of 2024 - 2027 and every 7th day from 1924 to
/// 2100, both in and outside of Israel.
/// </summary>
public class GoldenHebrewCalendarTests
{
    [Fact]
    public void JewishCalendarTefilaRulesAndFormatterMatchKosherJava()
    {
        var failures = new List<string>();
        string[]? header = null;
        var getters = new Dictionary<string, Func<object, object?>>();
        var rules = new TefilaRules();
        var he = new HebrewDateFormatter { IsHebrewFormat = true };
        var en = new HebrewDateFormatter();
        long compared = 0;
        foreach (string line in JavaApi.ReadLines("hebrew.tsv.gz"))
        {
            string[] f = line.Split('\t');
            switch (f[0])
            {
                case "#H":
                    header = f;
                    continue;
                case "N":
                    Check(failures, ref compared, "formatHebrewNumber " + f[1], f[2], he.FormatHebrewNumber(int.Parse(f[1], CultureInfo.InvariantCulture)));
                    continue;
                case "K":
                    Check(failures, ref compared, "getFormattedKviah " + f[1], f[2], he.GetFormattedKviah(int.Parse(f[1], CultureInfo.InvariantCulture)));
                    continue;
                case "H":
                    break;
                default:
                    continue;
            }
            var date = DateOnly.Parse(f[1], CultureInfo.InvariantCulture);
            bool israel = f[2] == "1";
            var jc = new JewishCalendar(date) { InIsrael = israel, UseModernHolidays = israel };
            string context = f[1] + (israel ? " (Israel)" : "");
            Check(failures, ref compared, context + " jewishDate", f[3], $"{jc.JewishYear}-{jc.JewishMonth}-{jc.JewishDayOfMonth}");
            int formatterIndex = 0;
            for (int i = 4; i < f.Length; i++)
            {
                string name = header![i];
                string expected = f[i];
                if (name.StartsWith("TefilaRules.", StringComparison.Ordinal))
                {
                    string methodName = name.Substring("TefilaRules.".Length);
                    MethodInfo method = typeof(TefilaRules).GetMethod(char.ToUpperInvariant(methodName[0]) + methodName.Substring(1),
                        new[] { typeof(JewishCalendar) })!;
                    Check(failures, ref compared, context + " " + name, expected, Format(method.Invoke(rules, new object[] { jc })));
                    continue;
                }
                if (name.StartsWith("he.", StringComparison.Ordinal) || name.StartsWith("en.", StringComparison.Ordinal))
                {
                    HebrewDateFormatter formatter = name.StartsWith("he.", StringComparison.Ordinal) ? he : en;
                    string actual = (formatterIndex++ % 10) switch
                    {
                        0 => formatter.Format(jc),
                        1 => formatter.FormatYomTov(jc),
                        2 => formatter.FormatRoshChodesh(jc),
                        3 => formatter.FormatParshah(jc),
                        4 => formatter.FormatSpecialParshah(jc),
                        5 => formatter.FormatOmer(jc),
                        6 => formatter.FormatDayOfWeek(jc),
                        7 => formatter.FormatTekufaName(jc),
                        8 => expected == "-" ? "-" : formatter.FormatDafYomiBavli(jc.GetDafYomiBavli()),
                        _ => expected == "-" ? "-" : formatter.FormatDafYomiYerushalmi(jc.GetDafYomiYerushalmi()),
                    };
                    Check(failures, ref compared, context + " " + name, expected, actual);
                    continue;
                }
                if (!getters.TryGetValue(name, out var getter))
                {
                    getter = JavaApi.Getter(typeof(JewishCalendar), name);
                    getters[name] = getter;
                }
                string actualValue;
                try
                {
                    actualValue = Format(getter(jc));
                }
                catch (Exception e)
                {
                    actualValue = expected.StartsWith("EX:", StringComparison.Ordinal)
                        && JavaApi.ExceptionType(expected.Substring(3)).IsInstanceOfType(e) ? expected : "EX:" + e.GetType().Name;
                }
                if (expected.StartsWith('I') && actualValue.StartsWith('I'))
                {
                    long diff = Math.Abs(long.Parse(expected.AsSpan(1), CultureInfo.InvariantCulture)
                        - long.Parse(actualValue.AsSpan(1), CultureInfo.InvariantCulture));
                    compared++;
                    if (diff > GoldenZmanimTests.ToleranceNanos)
                    {
                        failures.Add($"{context} {name}: expected {expected}, was {actualValue} (diff {diff} ns)");
                    }
                    continue;
                }
                Check(failures, ref compared, context + " " + name, expected, actualValue);
            }
        }
        Assert.True(compared > 500_000, $"only {compared} values compared");
        Assert.True(failures.Count == 0, $"{failures.Count} of {compared} values differ:\n" + string.Join("\n", failures.Take(60)));
    }

    private static void Check(List<string> failures, ref long compared, string context, string expected, string actual)
    {
        compared++;
        if (expected != actual)
        {
            failures.Add($"{context}: expected '{expected}', was '{actual}'");
        }
    }

    /// <summary>Formats a value the way the golden generator does.</summary>
    private static string Format(object? value) => value switch
    {
        null => "null",
        bool b => b ? "true" : "false",
        DateTimeOffset t => "I" + JavaApi.EpochNanos(t).ToString(CultureInfo.InvariantCulture),
        Daf d => "Daf" + d.MasechtaNumber + ":" + d.DafNumber,
        Enum e => "E" + ToJavaConstant(e.ToString()),
        IFormattable x => x.ToString(null, CultureInfo.InvariantCulture),
        _ => value.ToString() ?? "null",
    };

    /// <summary>Converts a .NET PascalCase enum member back to the Java <c>UPPER_SNAKE</c> constant.</summary>
    private static string ToJavaConstant(string name)
    {
        var sb = new StringBuilder();
        for (int i = 0; i < name.Length; i++)
        {
            if (i > 0 && char.IsUpper(name[i]))
            {
                sb.Append('_');
            }
            sb.Append(char.ToUpperInvariant(name[i]));
        }
        return sb.ToString();
    }
}
